using System.Data; using Microsoft.EntityFrameworkCore; using UnicoreCRM.BuildingBlocks;
namespace UnicoreCRM.Workflows.Atomic.Infrastructure.Persistence;
internal sealed class WorkflowIntegrationEventSource(WorkflowsDbContext db,TimeProvider clock):IIntegrationEventSource{
 public string SourceOwner=>"Workflows";
 public async Task<IntegrationEventLease?> ClaimAsync(int size,TimeSpan duration,CancellationToken ct){var now=clock.GetUtcNow();await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable,ct);var rows=await db.IntegrationOutboxMessages.Where(x=>(x.ExportState=="PENDING"&&(x.NextEligibleAt==null||x.NextEligibleAt<=now))||(x.ExportState=="LEASED"&&x.LeaseExpiresAt<=now)).OrderBy(x=>x.OccurredAt).Take(size).ToListAsync(ct);if(rows.Count==0){await tx.CommitAsync(ct);return null;}var id=Guid.NewGuid().ToString("N");var until=now.Add(duration);foreach(var x in rows)x.Lease(id,until);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return new(SourceOwner,id,until,rows.Select(x=>new IntegrationEventDraft(x.EventId,x.IntegrationEnvelopeJson)).ToArray());}
 public async Task AcknowledgeAsync(string id,IReadOnlyCollection<string> ids,CancellationToken ct){var rows=await db.IntegrationOutboxMessages.Where(x=>ids.Contains(x.EventId)&&x.RelayAttemptId==id).ToListAsync(ct);foreach(var x in rows)x.Publish(id,clock.GetUtcNow());if(rows.Count!=ids.Count)throw new InvalidOperationException("Relay acknowledgement does not own every lease.");await db.SaveChangesAsync(ct);}
 public async Task ReleaseAsync(string id,IReadOnlyCollection<string> ids,string error,DateTimeOffset next,CancellationToken ct){var rows=await db.IntegrationOutboxMessages.Where(x=>ids.Contains(x.EventId)&&x.RelayAttemptId==id).ToListAsync(ct);foreach(var x in rows)x.Release(id,error,next);await db.SaveChangesAsync(ct);}}
